using System;using System.IO;using System.Collections.Generic;using UnityEngine;
public class Script{public static string Main(){var go=new GameObject("native-size-random-probe"){hideFlags=HideFlags.HideAndDontSave};try{var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.startLifetime=10;m.startSize=1;m.startSpeed=0;m.maxParticles=1024;m.playOnAwake=false;var e=ps.emission;e.enabled=false;var shape=ps.shape;shape.enabled=false;var size=ps.sizeOverLifetime;size.enabled=true;size.separateAxes=true;size.x=new ParticleSystem.MinMaxCurve(0,1);size.y=new ParticleSystem.MinMaxCurve(0,1);size.z=new ParticleSystem.MinMaxCurve(0,1);ps.useAutoRandomSeed=false;ps.randomSeed=12345;ps.Play();ps.Pause();for(uint i=0;i<512;i++)ps.Emit(new ParticleSystem.EmitParams{randomSeed=unchecked(i*2654435761u+17u),startLifetime=10,startSize=1,velocity=Vector3.zero,applyShapeToPosition=false},1);ps.Simulate(1f/60,false,false,false);ps.Pause();var p=new ParticleSystem.Particle[1024];int count=ps.GetParticles(p);var rows=new List<object>();for(int i=0;i<count;i++){var v=p[i].GetCurrentSize3D(ps);rows.Add(new{seed=p[i].randomSeed,size=new[]{v.x,v.y,v.z}});}File.WriteAllText("OUTPUT_FILE",System.Text.Json.JsonSerializer.Serialize(new{unityVersion=Application.unityVersion,driver="EmitParams fixed seed; size-over-lifetime two constants 0..1",rows}));return "size samples "+count;}finally{UnityEngine.Object.DestroyImmediate(go);}}}
